from PTL_CAPACCT_INFO
where ACCT_TYPE = #{acctType,jdbcType=VARCHAR}
and PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
and CCY = #{ccy,jdbcType=VARCHAR}

select

from FIN_DEAL_PLEDGE
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and BRANCH = #{branch,jdbcType=DECIMAL}

select
    NVL(FSCR.SCALE, 0)
from FIN_STDSEC_CONVERSE_RADIO FSCR
where FSCR.FINPROD_ID = #{finprodId, jdbcType=VARCHAR}
  AND FSCR.BRANCH = '0'
  AND FSCR.VDATE  <= #{vdate, jdbcType=DATE}
  AND NOT EXISTS (SELECT 1
      FROM FIN_STDSEC_CONVERSE_RADIO FSCRINNER
      WHERE FSCRINNER.FINPROD_ID = FSCR.FINPROD_ID
        AND FSCRINNER.BRANCH ='0'
        AND FSCRINNER.VDATE <= #{vdate, jdbcType=DATE}
        AND FSCRINNER.VDATE > FSCR.VDATE
    )

SELECT

FROM
SETTLE_TRANS_DATA
WHERE
CJBH = #{sqcjbh, jdbcType=VARCHAR}

    AND SEAT_NUMBER = #{seatNumber, jdbcType=VARCHAR}


    AND SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}


    AND VDATE = #{vdate, jdbcType=DATE}
